-- Cria categoria 'Revenda' se não existir
INSERT INTO public.product_categories (name, color)
SELECT 'Revenda', '#F59E0B'
WHERE NOT EXISTS (SELECT 1 FROM public.product_categories WHERE name = 'Revenda');

